script:
frappe.ui.form.on("Project", {
	refresh(frm) {
		update_rate_mandatory_fields(frm);
	},
	custom_payment_scheme(frm) {
		update_rate_mandatory_fields(frm);
	},
	custom_ts_details_add(frm) {
		update_rate_mandatory_fields(frm);
	},
	validate(frm) {
		if (!frm.doc.custom_ts_details) {
			return;
		}
		const hasCost = !!frappe.meta.get_docfield("Project Team Details", "pt_cost_level");
		const hasCategory = !!frappe.meta.get_docfield("Project Team Details", "pt_category");
		if (!hasCost && !hasCategory) {
			return;
		}

		const isTimeAndMaterials = frm.doc.custom_payment_scheme === "Время и затраты (T&M)";
		const missingCost = [];
		const missingCategory = [];

		frm.doc.custom_ts_details.forEach((row, index) => {
			const rowNum = index + 1;
			if (hasCost && row.virtual_worker && !row.pt_cost_level) {
				missingCost.push(__("- {0} (строка {1})", [row.pt_role || "", rowNum]));
			}
			if (hasCategory && isTimeAndMaterials && !row.pt_category) {
				const who = row.pt_worker || row.pt_participant || __("виртуальный участник");
				missingCategory.push(__("- {0} (строка {1}, роль: {2})", [who, rowNum, row.pt_role || ""]));
			}
		});

		let message = "";
		if (missingCost.length) {
			message += __("Для виртуальных участников обязательно укажите ставку себестоимости:") + "<br><br>" + missingCost.join("<br>");
		}
		if (missingCategory.length) {
			if (message) {
				message += "<br><br>";
			}
			message += __("При схеме 'Время и затраты (T&M)' обязательно укажите ставку реализации:") + "<br><br>" + missingCategory.join("<br>");
		}
		if (message) {
			frappe.throw(message);
		}
	}
});

frappe.ui.form.on("Project Team Details", {
	virtual_worker(frm, cdt, cdn) {
		update_rate_mandatory_fields(frm);
	}
});

function update_rate_mandatory_fields(frm) {
	const grid = frm.fields_dict.custom_ts_details && frm.fields_dict.custom_ts_details.grid;
	if (!grid || !grid.grid_rows) {
		return;
	}
	const isTimeAndMaterials = frm.doc.custom_payment_scheme === "Время и затраты (T&M)";
	grid.grid_rows.forEach((row, index) => {
		if (!row.fields_dict) {
			return;
		}
		const rowData = frm.doc.custom_ts_details[index];
		const isVirtualWorker = !!(rowData && rowData.virtual_worker);
		if (row.fields_dict.pt_cost_level) {
			row.fields_dict.pt_cost_level.df.is_mandatory = isVirtualWorker;
			row.fields_dict.pt_cost_level.refresh();
		}
		if (row.fields_dict.pt_category) {
			row.fields_dict.pt_category.df.is_mandatory = isTimeAndMaterials;
			row.fields_dict.pt_category.refresh();
		}
	});
}

frappe.ui.form.on('Project', {
	refresh: function(frm) {
		if (!frm.doc.custom_ts_details || frm.is_new()) return;
		if (!frappe.meta.get_docfield('Project Team Details', 'base_cost_level')) return;
		calculate_levels(frm);
	},
});

async function calculate_levels(frm) {
	if (!frappe.meta.get_docfield('Project Team Details', 'base_cost_level')) {
		return;
	}
	if (!(await worker_doctype_exists())) {
		return;
	}

	const promises = frm.doc.custom_ts_details
		.filter(row => row.pt_participant)
		.map(row => calculate_row_level(frm, row));

	await Promise.all(promises);
	frm.refresh_field('custom_ts_details');
}

async function worker_doctype_exists() {
	try {
		return !!(await frappe.db.exists('DocType', 'Worker'));
	} catch (err) {
		return false;
	}
}

async function calculate_row_level(frm, row) {
	if (!row.pt_participant) return;

	try {
		const worker = await frappe.db.get_value('Worker',
			{ wuser: row.pt_participant },
			['name']
		);

		if (!worker?.message?.name) return;

		const workerDoc = await frappe.db.get_doc('Worker', worker.message.name);

		if (!workerDoc?.worker_level || workerDoc.worker_level.length === 0) return;

		const now = new Date();
		const validLevels = workerDoc.worker_level
			.filter(level => level.wl_valid_from && new Date(level.wl_valid_from) <= now)
			.sort((a, b) => new Date(b.wl_valid_from) - new Date(a.wl_valid_from));

		if (validLevels.length === 0) return;

		row.base_cost_level = validLevels[0].wl_cosl_level;

	} catch (err) {
		// Ошибки обрабатываются silently
		console.error(err);
	}
}

frappe.ui.form.on("Project", {
	validate(frm) {
		if (!frm.doc.custom_ts_details) {
			return;
		}
		if (!frappe.meta.get_docfield("Project Team Details", "virtual_worker")) {
			return;
		}

		const virtualParticipants = {};
		const errors = [];
		const hasWorker = !!frappe.meta.get_docfield("Project Team Details", "pt_worker");
		const hasApproval = !!frappe.meta.get_docfield("Project Team Details", "allow_approval");
		const hasPss = !!frappe.meta.get_docfield("Project Team Details", "pt_allow_pss");
		const hasLimitNotifications = !!frappe.meta.get_docfield(
			"Project Team Details",
			"notifications_on_limits"
		);

		frm.doc.custom_ts_details.forEach((row, index) => {
			const rowNum = index + 1;
			if (!row.virtual_worker) {
				return;
			}

			if (row.pt_participant_type) {
				row.pt_participant_type = null;
			}
			if (row.pt_participant) {
				row.pt_participant = null;
			}
			if (hasWorker && row.pt_worker) {
				row.pt_worker = null;
			}
			if (hasApproval && row.allow_approval) {
				row.allow_approval = 0;
			}
			if (hasPss && row.pt_allow_pss) {
				row.pt_allow_pss = 0;
			}
			if (hasLimitNotifications && row.notifications_on_limits) {
				row.notifications_on_limits = 0;
			}

			const virtualKey = row.pt_role + "_virtual";
			const existing = virtualParticipants[virtualKey];
			if (
				existing &&
				row.pt_valid_from &&
				row.pt_valid_for &&
				existing.pt_valid_from &&
				existing.pt_valid_for &&
				((row.pt_valid_from >= existing.pt_valid_from && row.pt_valid_from <= existing.pt_valid_for) ||
					(row.pt_valid_for >= existing.pt_valid_from && row.pt_valid_for <= existing.pt_valid_for))
			) {
				errors.push(
					__("Внимание! Виртуальный работник уже назначен на роль '{0}' в пересекающийся период (строки {1} и {2})", [
						row.pt_role,
						existing.idx,
						rowNum,
					])
				);
			}
			virtualParticipants[virtualKey] = {
				pt_valid_from: row.pt_valid_from,
				pt_valid_for: row.pt_valid_for,
				idx: rowNum,
			};
		});

		if (errors.length) {
			frappe.throw(errors.join("<br>"));
		}
	}
});

frappe.ui.form.on("Project Team Details", {
	virtual_worker(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (!row.virtual_worker) {
			return;
		}
		frappe.model.set_value(cdt, cdn, "pt_participant_type", null);
		frappe.model.set_value(cdt, cdn, "pt_participant", null);
		if (frappe.meta.get_docfield("Project Team Details", "pt_worker")) {
			frappe.model.set_value(cdt, cdn, "pt_worker", null);
		}
		if (frappe.meta.get_docfield("Project Team Details", "allow_approval")) {
			frappe.model.set_value(cdt, cdn, "allow_approval", 0);
		}
		if (frappe.meta.get_docfield("Project Team Details", "pt_allow_pss")) {
			frappe.model.set_value(cdt, cdn, "pt_allow_pss", 0);
		}
		if (frappe.meta.get_docfield("Project Team Details", "notifications_on_limits")) {
			frappe.model.set_value(cdt, cdn, "notifications_on_limits", 0);
		}
	}
});
